#!/usr/bin/env python3
"""Audit and safely maintain stack-aware .gitignore rules for QA projects."""

from __future__ import annotations

import argparse
import fnmatch
import json
import os
import re
import subprocess
from pathlib import Path
from typing import Any, Iterable


BEGIN_MARKER = "# BEGIN QA SKILL MANAGED"
END_MARKER = "# END QA SKILL MANAGED"
MANAGED_COMMENT = (
    "# Generated by generate-qa-from-test-cases. "
    "Keep examples and source configuration versioned."
)

BASE_PATTERNS = (
    ".env",
    ".env.*",
    "!.env.example",
    "!.env.sample",
    "!.env.template",
    "*.pem",
    "*.key",
    "*.p12",
    "*.pfx",
    "*.log",
    "*.swp",
    "*.swo",
    "*~",
    ".idea/",
    ".DS_Store",
    "Thumbs.db",
)
QA_PATTERNS = (
    "qa-artifacts/",
    "qa-history/",
    "playwright/.auth/",
    "storage-state*.json",
    "auth-state*.json",
    "playwright-report/",
    "test-results/",
    "blob-report/",
    "allure-results/",
    "allure-report/",
)
STACK_PATTERNS = {
    "python": (
        ".venv/",
        "venv/",
        "__pycache__/",
        "*.py[cod]",
        ".pytest_cache/",
        ".coverage",
        "htmlcov/",
        ".mypy_cache/",
        ".ruff_cache/",
        ".tox/",
        ".nox/",
    ),
    "node": (
        "node_modules/",
        ".npm/",
        ".pnpm-store/",
        "dist/",
        "build/",
        "coverage/",
        ".playwright/",
        ".next/",
        ".nuxt/",
        ".cache/",
    ),
    "java": (
        "target/",
        ".gradle/",
        "build/",
    ),
    "dotnet": (
        "bin/",
        "obj/",
        ".vs/",
        "TestResults/",
        "*.user",
        "*.suo",
    ),
}
STACK_MARKERS = {
    "python": (
        "pyproject.toml",
        "setup.py",
        "setup.cfg",
        "Pipfile",
        "poetry.lock",
    ),
    "node": (
        "package.json",
        "package-lock.json",
        "pnpm-lock.yaml",
        "yarn.lock",
    ),
    "java": (
        "pom.xml",
        "build.gradle",
        "build.gradle.kts",
        "settings.gradle",
        "settings.gradle.kts",
        "gradlew",
    ),
    "dotnet": (
        "global.json",
        "Directory.Build.props",
        "Directory.Build.targets",
    ),
}
EXCLUDED_DIRECTORIES = {
    ".git",
    ".hg",
    ".svn",
    ".terraform",
    ".venv",
    ".vs",
    "__pycache__",
    "bin",
    "blob-report",
    "build",
    "coverage",
    "dist",
    "htmlcov",
    "node_modules",
    "obj",
    "playwright-report",
    "qa-artifacts",
    "qa-history",
    "target",
    "test-results",
    "vendor",
}
SAFE_EXAMPLE_PARTS = {
    "example",
    "sample",
    "template",
}
SENSITIVE_GLOBS = (
    ".env",
    ".env.*",
    "*.pem",
    "*.key",
    "*.p12",
    "*.pfx",
    "storage-state*.json",
    "auth-state*.json",
)
CONDITIONAL_SECRET_NAMES = {
    ".npmrc",
    ".pypirc",
    ".netrc",
    "credentials.json",
    "secrets.json",
    "service-account.json",
    "service_account.json",
}
SECRET_KEY = re.compile(
    r"(?i)(?:^|[^a-z])"
    r"(?:auth(?:orization)?|client[_-]?secret|connection[_-]?string|"
    r"credential|password|private[_-]?key|secret|token)"
    r"(?:[^a-z]|$)"
)
ENV_REFERENCE = re.compile(
    r"^(?:\$\{[A-Za-z_][A-Za-z0-9_]*\}|"
    r"\$[A-Za-z_][A-Za-z0-9_]*|"
    r"%[A-Za-z_][A-Za-z0-9_]*%)$"
)


class GitignoreError(RuntimeError):
    pass


def validate_extra_patterns(patterns: Iterable[str]) -> list[str]:
    validated = unique(patterns)
    forbidden_broad = {
        "*",
        "**",
        "/*",
        "*.json",
        "*.csv",
        "config/",
        "/config/",
        "data/",
        "/data/",
    }
    protected = {
        "qa-project.yaml",
        "qa-knowledge",
        "qa-knowledge/",
        ".env.example",
        ".env.sample",
        ".env.template",
    }
    for pattern in validated:
        normalized = pattern.lstrip("/")
        if (
            "\n" in pattern
            or "\r" in pattern
            or "\0" in pattern
            or pattern.startswith(("#", "!"))
            or pattern in {BEGIN_MARKER, END_MARKER}
        ):
            raise GitignoreError(
                f"Unsafe additional .gitignore pattern: {pattern!r}"
            )
        if pattern in forbidden_broad:
            raise GitignoreError(
                f"Overly broad additional .gitignore pattern: {pattern!r}"
            )
        if normalized in protected or normalized.startswith("qa-knowledge/"):
            raise GitignoreError(
                f"Protected source path cannot be ignored: {pattern!r}"
            )
    return validated


def unique(values: Iterable[str]) -> list[str]:
    result: list[str] = []
    for value in values:
        normalized = value.strip()
        if normalized and normalized not in result:
            result.append(normalized)
    return result


def detect_stacks(root: Path) -> list[str]:
    stacks: list[str] = []
    for stack, markers in STACK_MARKERS.items():
        if any((root / marker).exists() for marker in markers):
            stacks.append(stack)

    if any(root.glob("*.csproj")) or any(root.glob("*.sln")):
        if "dotnet" not in stacks:
            stacks.append("dotnet")

    requirements = (
        list(root.glob("requirements*.txt"))
        + list(root.glob("requirements/*.txt"))
    )
    if requirements and "python" not in stacks:
        stacks.append("python")
    return stacks


def safe_example(path: Path) -> bool:
    parts = {part.lower() for part in re.split(r"[._-]+", path.name)}
    return bool(parts & SAFE_EXAMPLE_PARTS)


def value_is_reference(value: str) -> bool:
    normalized = value.strip().strip("\"'")
    return not normalized or bool(ENV_REFERENCE.fullmatch(normalized))


def conditional_file_looks_sensitive(path: Path, max_size: int) -> bool:
    try:
        if path.stat().st_size > max_size:
            return True
        text = path.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return True

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith(("#", ";")):
            continue
        separator = "=" if "=" in line else ":" if ":" in line else ""
        if separator:
            key, value = line.split(separator, 1)
            if SECRET_KEY.search(key) and not value_is_reference(value.rstrip(",")):
                return True
        elif SECRET_KEY.search(line) and not any(
            reference in line for reference in ("${", "$(", "process.env")
        ):
            return True
    return False


def is_sensitive_candidate(path: Path, max_secret_file_size: int) -> bool:
    if safe_example(path):
        return False
    name = path.name
    if any(fnmatch.fnmatch(name, pattern) for pattern in SENSITIVE_GLOBS):
        return True
    if (
        name in CONDITIONAL_SECRET_NAMES
        or fnmatch.fnmatch(name, "service-account*.json")
        or fnmatch.fnmatch(name, "service_account*.json")
    ):
        return conditional_file_looks_sensitive(path, max_secret_file_size)
    return False


def scan_sensitive_files(
    root: Path,
    *,
    max_files: int,
    max_secret_file_size: int,
) -> tuple[list[Path], bool]:
    candidates: list[Path] = []
    scanned = 0
    truncated = False

    for directory, names, files in os.walk(root):
        names[:] = sorted(
            name for name in names if name not in EXCLUDED_DIRECTORIES
        )
        current = Path(directory)
        for filename in sorted(files):
            if scanned >= max_files:
                truncated = True
                break
            scanned += 1
            path = current / filename
            if is_sensitive_candidate(path, max_secret_file_size):
                candidates.append(path)
        if truncated:
            break
    return candidates, truncated


def exact_pattern_for(path: Path, root: Path) -> str:
    relative = path.relative_to(root).as_posix()
    if "/" in relative:
        return f"/{relative}"
    return relative


def planned_patterns(
    root: Path,
    stacks: Iterable[str],
    sensitive_files: Iterable[Path],
    extras: Iterable[str],
) -> list[str]:
    patterns: list[str] = [*BASE_PATTERNS, *QA_PATTERNS]
    for stack in stacks:
        patterns.extend(STACK_PATTERNS[stack])
    for path in sensitive_files:
        if path.name in CONDITIONAL_SECRET_NAMES or path.suffix.lower() == ".json":
            patterns.append(exact_pattern_for(path, root))
    patterns.extend(extras)
    return unique(patterns)


def read_gitignore(path: Path) -> str:
    if not path.exists():
        return ""
    try:
        return path.read_text(encoding="utf-8")
    except OSError as exc:
        raise GitignoreError(f"Unable to read {path}: {exc}") from exc


def parse_active_patterns(text: str) -> list[str]:
    return [
        line.strip()
        for line in text.splitlines()
        if line.strip() and not line.lstrip().startswith("#")
    ]


def render_managed_block(patterns: Iterable[str]) -> str:
    return "\n".join(
        [BEGIN_MARKER, MANAGED_COMMENT, *patterns, END_MARKER]
    )


def update_managed_block(existing: str, patterns: Iterable[str]) -> str:
    lines = existing.splitlines()
    starts = [index for index, line in enumerate(lines) if line == BEGIN_MARKER]
    ends = [index for index, line in enumerate(lines) if line == END_MARKER]
    if len(starts) != len(ends) or len(starts) > 1:
        raise GitignoreError(
            "Malformed QA-managed .gitignore block; fix duplicate or missing markers"
        )

    block = render_managed_block(patterns).splitlines()
    if starts:
        start = starts[0]
        end = ends[0]
        if end < start:
            raise GitignoreError(
                "Malformed QA-managed .gitignore block; end marker precedes start"
            )
        result = [*lines[:start], *block, *lines[end + 1 :]]
    else:
        result = list(lines)
        if result and result[-1] != "":
            result.append("")
        result.extend(block)

    while result and result[-1] == "":
        result.pop()
    return "\n".join(result) + "\n"


def write_gitignore(path: Path, text: str) -> None:
    try:
        path.write_text(text, encoding="utf-8")
    except OSError as exc:
        raise GitignoreError(f"Unable to update {path}: {exc}") from exc


def git_repository_root(root: Path) -> Path | None:
    try:
        result = subprocess.run(
            ["git", "-C", str(root), "rev-parse", "--show-toplevel"],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            check=False,
            timeout=10,
        )
    except (OSError, subprocess.TimeoutExpired):
        return None
    if result.returncode != 0:
        return None
    return Path(result.stdout.strip()).resolve()


def git_tracks(path: Path, repository_root: Path | None) -> bool:
    if repository_root is None:
        return False
    try:
        relative = path.resolve().relative_to(repository_root).as_posix()
    except ValueError:
        return False
    try:
        result = subprocess.run(
            [
                "git",
                "-C",
                str(repository_root),
                "ls-files",
                "--error-unmatch",
                "--",
                relative,
            ],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
            timeout=10,
        )
    except (OSError, subprocess.TimeoutExpired):
        return False
    return result.returncode == 0


def audit_project(root: Path, args: argparse.Namespace) -> dict[str, Any]:
    root = root.resolve()
    if not root.is_dir():
        raise GitignoreError(f"Project root does not exist: {root}")

    gitignore = root / ".gitignore"
    existing = read_gitignore(gitignore)
    stacks = detect_stacks(root)
    candidates, scan_truncated = scan_sensitive_files(
        root,
        max_files=args.max_files,
        max_secret_file_size=args.max_secret_file_size,
    )
    patterns = planned_patterns(root, stacks, candidates, args.extra_pattern)
    active_patterns = parse_active_patterns(existing)
    missing_patterns = [
        pattern for pattern in patterns if pattern not in active_patterns
    ]
    repository_root = git_repository_root(root)
    tracked_sensitive = [
        str(path.relative_to(root))
        for path in candidates
        if git_tracks(path, repository_root)
    ]

    updated = False
    if args.apply:
        new_text = update_managed_block(existing, patterns)
        if new_text != existing:
            write_gitignore(gitignore, new_text)
            updated = True

    if tracked_sensitive:
        status = "BLOCKED_TRACKED_SENSITIVE"
    elif args.apply:
        status = "UPDATED" if updated else "READY"
    elif missing_patterns:
        status = "CHANGES_REQUIRED"
    else:
        status = "READY"

    return {
        "project": str(root),
        "gitignore": str(gitignore),
        "git_repository": str(repository_root) if repository_root else None,
        "detected_stacks": stacks,
        "status": status,
        "apply_requested": args.apply,
        "updated": updated,
        "planned_patterns": patterns,
        "missing_patterns": missing_patterns,
        "sensitive_candidates": [
            str(path.relative_to(root)) for path in candidates
        ],
        "tracked_sensitive": tracked_sensitive,
        "scan_truncated": scan_truncated,
        "values_exposed": False,
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--project",
        action="append",
        type=Path,
        default=[],
        help="Project root; repeat for frontend, backend, automation and performance",
    )
    parser.add_argument(
        "--extra-pattern",
        action="append",
        default=[],
        help="Additional reviewed .gitignore pattern; repeat as needed",
    )
    parser.add_argument(
        "--apply",
        action="store_true",
        help="Create or update only the QA-managed block after preview",
    )
    parser.add_argument("--max-files", type=int, default=20_000)
    parser.add_argument("--max-secret-file-size", type=int, default=1_000_000)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()

    projects: list[Path] = []
    seen: set[Path] = set()
    for project in args.project or [Path(".")]:
        resolved = project.resolve()
        if resolved not in seen:
            projects.append(resolved)
            seen.add(resolved)

    try:
        args.extra_pattern = validate_extra_patterns(args.extra_pattern)
        reports = [audit_project(project, args) for project in projects]
    except GitignoreError as exc:
        rendered = {
            "status": "ERROR",
            "error": str(exc),
            "values_exposed": False,
        }
        print(json.dumps(rendered, ensure_ascii=False, indent=2))
        return 2

    blocking_count = sum(
        report["status"] == "BLOCKED_TRACKED_SENSITIVE"
        for report in reports
    )
    changes_required = sum(
        report["status"] == "CHANGES_REQUIRED" for report in reports
    )
    if blocking_count:
        status = "BLOCKED"
    elif changes_required:
        status = "CHANGES_REQUIRED"
    else:
        status = "READY"

    result = {
        "status": status,
        "project_count": len(reports),
        "blocking_count": blocking_count,
        "changes_required_count": changes_required,
        "projects": reports,
        "values_exposed": False,
    }
    rendered = json.dumps(result, ensure_ascii=False, indent=2)
    print(rendered)
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(rendered + "\n", encoding="utf-8")
    return 0 if status == "READY" else 1


if __name__ == "__main__":
    raise SystemExit(main())
